package id.tensky.coldspot

import android.content.Context
import android.content.res.AssetManager
import android.util.Base64
import android.util.Log
import org.jacoco.core.analysis.Analyzer
import org.jacoco.core.analysis.CoverageBuilder
import org.jacoco.core.data.ExecutionDataReader
import org.jacoco.core.data.ExecutionDataStore
import org.jacoco.core.data.SessionInfoStore
import java.io.ByteArrayInputStream

/**
 * The spike's debug screen, without a screen: reads the JaCoCo agent, runs the Analyzer on every class shipped
 * by every module under `assets/coldspot/`, and logs what the runtime will one day render. Coverage variant only.
 *
 * Lines, tag `ColdSpot`, all parsed by the laptop-side check (`checkDeviceRun`):
 *   EXEC <i>/<n> <base64>         the agent's execution data, in Logcat-sized chunks
 *   CLASS <vm name> module=<m> id=<hex> noMatch=<bool> lines=<first>..<last>
 *   LINE <vm name> <line> <covered>/<total>   instruction counters, executable lines only
 *   DONE <classes> classes, <ms> ms
 */
object CoverageDebug {
    private const val TAG = "ColdSpot"

    @JvmStatic
    fun run(context: Context) {
        Thread {
            try {
                analyze(context)
            } catch (e: Throwable) {
                Log.e(TAG, "analysis failed", e)
            }
        }.start()
    }

    private fun analyze(context: Context) {
        val started = System.currentTimeMillis()
        val exec = readAgent()
        val encoded = Base64.encodeToString(exec, Base64.NO_WRAP)
        val chunks = encoded.chunked(3_000)
        chunks.forEachIndexed { i, chunk -> Log.i(TAG, "EXEC ${i + 1}/${chunks.size} $chunk") }

        val store = ExecutionDataStore()
        ExecutionDataReader(ByteArrayInputStream(exec)).apply {
            setExecutionDataVisitor(store)
            setSessionInfoVisitor(SessionInfoStore())
            read()
        }

        var classes = 0
        val assets = context.assets
        for (module in modulesUnder(assets, "coldspot")) {
            for (path in classFilesUnder(assets, "coldspot/$module/classes")) {
                val bytes = assets.open(path).use { it.readBytes() }
                val builder = CoverageBuilder()
                Analyzer(store, builder).analyzeClass(bytes, path)
                for (cls in builder.classes) {
                    classes++
                    Log.i(TAG, "CLASS ${cls.name} module=$module id=${java.lang.Long.toHexString(cls.id)} noMatch=${cls.isNoMatch} lines=${cls.firstLine}..${cls.lastLine}")
                    if (cls.firstLine < 0) continue
                    for (line in cls.firstLine..cls.lastLine) {
                        val counter = cls.getLine(line).instructionCounter
                        if (counter.totalCount == 0) continue
                        Log.i(TAG, "LINE ${cls.name} $line ${counter.coveredCount}/${counter.totalCount}")
                    }
                }
            }
        }
        Log.i(TAG, "DONE $classes classes, ${System.currentTimeMillis() - started} ms")
    }

    /** FINDINGS Finding 1: the agent, never a `$jacocoData` field. */
    private fun readAgent(): ByteArray {
        val rt = Class.forName("org.jacoco.agent.rt.RT")
        val agent = rt.getMethod("getAgent").invoke(null)
        return agent.javaClass.getMethod("getExecutionData", Boolean::class.javaPrimitiveType).invoke(agent, false) as ByteArray
    }

    /**
     * The module folders under [dir], however deep (`app`, `feature`, `lib/core`): those holding a module manifest.
     * The shared `manifest.json` at the root is a file, not a module.
     */
    private fun modulesUnder(assets: AssetManager, dir: String, prefix: String = ""): List<String> {
        val names = assets.list(dir).orEmpty()
        if (prefix.isNotEmpty() && "manifest.json" in names) return listOf(prefix.removeSuffix("/"))
        return names.filter { '.' !in it }.flatMap { modulesUnder(assets, "$dir/$it", "$prefix$it/") }
    }

    private fun classFilesUnder(assets: AssetManager, dir: String): List<String> =
        assets.list(dir).orEmpty().flatMap { name ->
            val path = "$dir/$name"
            if (name.endsWith(".class")) listOf(path) else classFilesUnder(assets, path)
        }
}

package id.tensky.coldspot

import android.app.Application
import dagger.hilt.android.HiltAndroidApp

@HiltAndroidApp
class ColdSpotApp : Application()

package id.tensky.coldspot

import android.content.Context
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.enableEdgeToEdge
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.tooling.preview.PreviewParameter
import androidx.compose.ui.tooling.preview.PreviewParameterProvider
import dagger.hilt.android.AndroidEntryPoint
import id.tensky.coldspot.feature.FeatureScreen
import id.tensky.coldspot.feature.Greeter
import id.tensky.coldspot.feature.Pricing
import id.tensky.coldspot.feature.ThemePreviews
import id.tensky.coldspot.ui.theme.ColdSpotTheme
import javax.inject.Inject

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    @Inject
    lateinit var greeter: Greeter

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        // Exercises one arm of each branch in :feature, so the coverage dump has something to show.
        val price = Pricing().price(3)
        setContent {
            ColdSpotTheme {
                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
                    Column(modifier = Modifier.padding(innerPadding)) {
                        Greeting(name = greeter.greet("ColdSpot"))
                        Text(text = "3 cost $price")
                        FeatureScreen(items = 3)
                    }
                }
            }
        }
        scheduleCoverageDump()
    }

    /** In the coverage variant only, where CoverageDebug exists: dump the JaCoCo analysis to Logcat once the screen is up. */
    private fun scheduleCoverageDump() {
        val hook = runCatching { Class.forName("id.tensky.coldspot.CoverageDebug") }.getOrNull() ?: return
        window.decorView.postDelayed({ hook.getMethod("run", Context::class.java).invoke(null, applicationContext) }, 3_000)
    }
}

@Composable
fun Greeting(name: String, modifier: Modifier = Modifier) {
    Text(
        text = "$name!",
        modifier = modifier
    )
}

// The previews below never run in the app: the bundle lists their lines as preview lines, neutral, never red.

@Preview(showBackground = true)
@Composable
fun GreetingPreview() {
    ColdSpotTheme {
        Greeting("ColdSpot")
    }
}

/** A multipreview from :feature, so the annotation has to be found on the compile classpath. */
@ThemePreviews
@Composable
fun GreetingThemePreview() {
    ColdSpotTheme {
        Greeting("Themes")
    }
}

/** Preview-only, like the preview it feeds. */
class GreetingNames : PreviewParameterProvider<String> {
    override val values = sequenceOf("Ada", "Grace")
}

@Preview
@Composable
fun GreetingNamesPreview(@PreviewParameter(GreetingNames::class) name: String) {
    ColdSpotTheme {
        Greeting(name)
    }
}

package id.tensky.coldspot.feature

import androidx.compose.foundation.layout.Column
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier

/** A composable with a branch: the spike's second subject for a library module. */
@Composable
fun FeatureScreen(items: Int, modifier: Modifier = Modifier) {
    Column(modifier = modifier) {
        if (items == 0) {
            Text(text = "Nothing yet")
        } else {
            Text(text = "$items items")
        }
    }
}

package id.tensky.coldspot.feature

import javax.inject.Inject

/** Injected into the app's activity by Hilt. */
class Greeter @Inject constructor() {
    fun greet(name: String): String = "Hello, $name"
}

package id.tensky.coldspot.feature

/** A plain class with a branch: the spike's subject for a library module. */
class Pricing {
    fun price(quantity: Int): Int {
        return if (quantity >= 10) {
            quantity * 9
        } else {
            quantity * 10
        }
    }
}

package id.tensky.coldspot.feature

import android.content.res.Configuration.UI_MODE_NIGHT_YES
import androidx.compose.ui.tooling.preview.Preview

/** A multipreview, light and dark, defined here and used by the app: the preview lookup has to cross modules to see it. */
@Preview(name = "light")
@Preview(name = "dark", uiMode = UI_MODE_NIGHT_YES)
annotation class ThemePreviews

package com.google.samples.apps.nowinandroid

import android.content.Context
import android.content.res.AssetManager
import android.util.Base64
import android.util.Log
import org.jacoco.core.analysis.Analyzer
import org.jacoco.core.analysis.CoverageBuilder
import org.jacoco.core.data.ExecutionDataReader
import org.jacoco.core.data.ExecutionDataStore
import org.jacoco.core.data.SessionInfoStore
import java.io.ByteArrayInputStream

/**
 * ColdSpot 4e temporary hook (coverage source set only): reads the JaCoCo agent, runs the Analyzer on every class
 * every module shipped under assets/coldspot/, logs EXEC chunks, CLASS and LINE rows with tag ColdSpot, for
 * `./gradlew :tooling:plugin:checkDeviceRun -Plogcat=<dump> -Papk=<apk>` on the laptop. Triggered by
 * [CoverageDumpReceiver].
 */
object CoverageDebug {
    private const val TAG = "ColdSpot"

    @JvmStatic
    fun run(context: Context) {
        Thread {
            try {
                analyze(context)
            } catch (e: Throwable) {
                Log.e(TAG, "analysis failed", e)
            }
        }.start()
    }

    private fun analyze(context: Context) {
        val started = System.currentTimeMillis()
        val exec = readAgent()
        val chunks = Base64.encodeToString(exec, Base64.NO_WRAP).chunked(3_000)
        chunks.forEachIndexed { i, chunk -> Log.i(TAG, "EXEC ${i + 1}/${chunks.size} $chunk") }

        val store = ExecutionDataStore()
        ExecutionDataReader(ByteArrayInputStream(exec)).apply {
            setExecutionDataVisitor(store)
            setSessionInfoVisitor(SessionInfoStore())
            read()
        }

        var classes = 0
        val assets = context.assets
        for (module in modulesUnder(assets, "coldspot")) {
            for (path in classFilesUnder(assets, "coldspot/$module/classes")) {
                val bytes = assets.open(path).use { it.readBytes() }
                val builder = CoverageBuilder()
                Analyzer(store, builder).analyzeClass(bytes, path)
                for (cls in builder.classes) {
                    classes++
                    Log.i(TAG, "CLASS ${cls.name} module=$module id=${java.lang.Long.toHexString(cls.id)} noMatch=${cls.isNoMatch} lines=${cls.firstLine}..${cls.lastLine}")
                    if (cls.firstLine < 0) continue
                    for (line in cls.firstLine..cls.lastLine) {
                        val counter = cls.getLine(line).instructionCounter
                        if (counter.totalCount == 0) continue
                        Log.i(TAG, "LINE ${cls.name} $line ${counter.coveredCount}/${counter.totalCount}")
                    }
                }
            }
        }
        Log.i(TAG, "DONE $classes classes, ${System.currentTimeMillis() - started} ms")
    }

    private fun readAgent(): ByteArray {
        val rt = Class.forName("org.jacoco.agent.rt.RT")
        val agent = rt.getMethod("getAgent").invoke(null)
        return agent.javaClass.getMethod("getExecutionData", Boolean::class.javaPrimitiveType).invoke(agent, false) as ByteArray
    }

    /** Module folders under [dir], however deep (`app`, `core/designsystem`, `feature/foryou/impl`): those holding a manifest. */
    private fun modulesUnder(assets: AssetManager, dir: String, prefix: String = ""): List<String> {
        val names = assets.list(dir).orEmpty()
        // The root holds the shared manifest.json, which is not a module's.
        if (prefix.isNotEmpty() && "manifest.json" in names) return listOf(prefix.removeSuffix("/"))
        return names.filter { '.' !in it }.flatMap { modulesUnder(assets, "$dir/$it", "$prefix$it/") }
    }

    private fun classFilesUnder(assets: AssetManager, dir: String): List<String> =
        assets.list(dir).orEmpty().flatMap { name ->
            val path = "$dir/$name"
            if (name.endsWith(".class")) listOf(path) else classFilesUnder(assets, path)
        }
}

package com.google.samples.apps.nowinandroid

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent

/**
 * ColdSpot 4e temporary hook: `adb shell am broadcast -a com.google.samples.apps.nowinandroid.COLDSPOT_DUMP
 * -n <applicationId>/com.google.samples.apps.nowinandroid.CoverageDumpReceiver` dumps the analysis to Logcat.
 */
class CoverageDumpReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        CoverageDebug.run(context.applicationContext)
    }
}

package id.tensky.coldspot.bundle

import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import java.io.File
import java.io.IOException

/**
 * Cuts one module's bundle from [changes]: under `[coldspotDir]/[module]/`, the original bytes of every compiled
 * class of the module that the change touches, as `classes/<vm/Name>.class`, and `manifest.json`, described by
 * [ModuleManifest]. With [sharedManifest], also `[coldspotDir]/manifest.json`, the [Manifest] of the whole
 * change, which the application module alone writes, naming [jacoco], the JaCoCo whose instrumenter the build
 * uses. Everything written here is replaced on every call; nothing else under [coldspotDir] is touched, so
 * modules never disturb each other's folders.
 *
 * Changed files that [excludes] match are noise: they get no classes, no blind lines, and no entry in the module
 * manifest, but they are never dropped in silence. The shared manifest lists each with the rule that matched,
 * and so does the [BundleReport].
 *
 * [classDirs] are compile outputs, Kotlin's and Java's, walked for `.class` files in that order. Their
 * `SourceFile`, `LineNumberTable` and SMAP attributes decide which ship and which lines are blind, and their
 * annotations which changed lines are Compose previews ([PreviewFinder]), with [classpath], the module's compile
 * classpath, consulted for annotation classes and supertypes the module does not hold. A class two directories
 * hold compiled differently ([ConflictingClass]) is read from the first, as the transform ships it, and reported;
 * only when it is a class the change touches, which the bundle would ship, is that an error: there is then no
 * telling which compilation the app is meant to run. The [BundleReport] says what did not ship, and why.
 * Nothing is logged.
 *
 * @throws IllegalStateException when a class the change touches is compiled differently in two of [classDirs],
 *   or a class carries an SMAP that cannot be read
 * @throws IOException when a changed source file or a class file cannot be read
 */
@Throws(IOException::class)
public fun buildBundle(
    changes: RepositoryChanges,
    excludes: ExcludeRules,
    module: String,
    classDirs: List<File>,
    classpath: List<File>,
    coldspotDir: File,
    sharedManifest: Boolean,
    jacoco: Manifest.Jacoco,
): BundleReport {
    val excluded = ArrayList<Manifest.ExcludedFile>()
    val measured = LinkedHashMap<String, Set<Int>>()
    for ((path, lines) in changes.changedLines) {
        val rule = excludes.matching(path)
        if (rule == null) measured[path] = lines else excluded += Manifest.ExcludedFile(path, lines.size, rule)
    }

    val (classes, conflicts) = readClasses(classDirs)
    val selection = selectClasses(measured, classes, lazy { changes.sourceFiles })
    val shipped = selection.classesByFile.values.flatten().mapTo(HashSet()) { it.name }
    conflicts.firstOrNull { it.className in shipped }?.let { conflict ->
        throw IllegalStateException(
            "${conflict.className} is compiled differently in ${conflict.kept} and ${conflict.dropped}, and the change touches it: " +
                "ColdSpot cannot tell which of the two the app is meant to run. Have the build compile it once (a clean build " +
                "usually does), or leave its file out with coldSpot { exclude(...) }.",
        )
    }
    val previewsByFile = ClassLookup(classpath).use { lookup ->
        val finder = PreviewFinder(classes.associateBy { it.name }, lookup)
        selection.classesOfFile.mapValues { (path, placed) -> previewLines(measured.getValue(path), placed.flatMap(finder::previewRangesOf)) }
            .filterValues { it.isNotEmpty() }
    }
    val moduleFiles = measured.keys.mapNotNull { path ->
        val shipped = selection.classesByFile[path]?.map { it.name } ?: emptyList()
        val blind = selection.blindLinesByFile[path]?.toList() ?: emptyList()
        val previews = previewsByFile[path] ?: emptyList()
        if (shipped.isEmpty() && blind.isEmpty() && previews.isEmpty()) null else ModuleManifest.ModuleFile(path, shipped, blind, previews)
    }
    val moduleDir = File(coldspotDir, module)
    writeModule(moduleDir, ModuleManifest(Manifest.SCHEMA_VERSION, module, moduleFiles), selection.classesByFile.values.flatten())

    if (sharedManifest) {
        val files = measured.map { (path, lines) -> Manifest.ChangedFile(path, lines.toList(), File(changes.workTree, path).readText()) }
        coldspotDir.mkdirs()
        File(coldspotDir, MANIFEST).writeText(JSON.encodeToString(Manifest(Manifest.SCHEMA_VERSION, changes.base, changes.head, changes.commits, jacoco, files, excluded)))
    }

    return BundleReport(
        classesByFile = selection.classesByFile.mapValues { (_, classes) -> classes.map { it.name } },
        ambiguous = selection.ambiguous,
        filesWithoutClasses = measured.keys.filter { it !in selection.classesByFile },
        blindLinesByFile = selection.blindLinesByFile.mapValues { (_, lines) -> lines.toList() },
        previewLinesByFile = previewsByFile,
        excluded = excluded,
        conflicts = conflicts,
    )
}

/** The changed lines that fall in a preview's range, grouped by preview in line order; a line in two ranges goes to the first. */
private fun previewLines(changedLines: Set<Int>, ranges: List<PreviewRange>): List<ModuleManifest.PreviewLines> {
    val byRange = LinkedHashMap<PreviewRange, MutableList<Int>>()
    for (line in changedLines.sorted()) {
        val range = ranges.firstOrNull { line in it.lines } ?: continue
        byRange.getOrPut(range) { ArrayList() } += line
    }
    return byRange.map { (range, lines) -> ModuleManifest.PreviewLines(lines, range.reason) }
}

/** What [buildBundle] made of the classes it was given, for the build to relay however it sees fit. */
public class BundleReport(
    /** Changed file → the VM names of the classes shipped for it, both ascending. Files that got none are absent. */
    public val classesByFile: Map<String, List<String>>,
    /** Classes the change touches that could belong to more than one changed file, and were therefore left out. */
    public val ambiguous: List<AmbiguousClass>,
    /** Measured changed files no shipped class was attributed to: their lines cannot be coloured, blind ones aside. */
    public val filesWithoutClasses: List<String>,
    /** Changed file → its lines that run only inside classes that cannot ship; see [ModuleManifest.ModuleFile.blindLines]. */
    public val blindLinesByFile: Map<String, List<Int>>,
    /** Changed file → its lines that are previews, by preview; see [ModuleManifest.ModuleFile.previews]. Files with none are absent. */
    public val previewLinesByFile: Map<String, List<ModuleManifest.PreviewLines>>,
    /** Changed files the rules left out, each with the rule; the same list the shared manifest carries. */
    public val excluded: List<Manifest.ExcludedFile>,
    /** Classes two class directories hold compiled differently, read from the first; none of them shipped, or the bundle would have failed. */
    public val conflicts: List<ConflictingClass>,
)

/** A class whose `SourceFile` names several changed files and whose package settles on none of them. */
public data class AmbiguousClass(
    /** The VM name. */
    public val className: String,
    public val sourceFile: String,
    /** The changed files it could belong to, in path order. */
    public val candidates: List<String>,
)

/** The file name of both manifests, at `coldspot/` and at `coldspot/<module>/`. */
public const val MANIFEST: String = "manifest.json"

private val JSON = Json {
    prettyPrint = true
    encodeDefaults = true
}

private fun writeModule(moduleDir: File, manifest: ModuleManifest, classes: List<CompiledClass>) {
    val classesDir = File(moduleDir, "classes")
    classesDir.deleteRecursively()
    for (cls in classes) {
        File(classesDir, "${cls.name}.class").apply {
            parentFile.mkdirs()
            writeBytes(cls.bytes)
        }
    }
    moduleDir.mkdirs()
    File(moduleDir, MANIFEST).writeText(JSON.encodeToString(manifest))
}

package id.tensky.coldspot.bundle

import java.io.Closeable
import java.io.File
import java.io.IOException
import java.util.zip.ZipFile

/**
 * Class files by VM name from a compile classpath: directories and jars, searched in order, the first hit
 * winning as a compiler's would. Jars are opened on the first lookup that reaches them and kept open until
 * [close], so that the many lookups of one bundle open each jar once. Every lookup is remembered, misses
 * included. An entry that is neither a directory nor a zip holds no classes.
 */
internal class ClassLookup(entries: List<File>) : Closeable {
    private val entries = entries.filter { it.exists() }
    private val jars = HashMap<File, ZipFile?>()
    private val found = HashMap<String, ByteArray?>()

    /** The bytes of the class called [vmName] (`com/acme/Thing`), or null when the classpath has none. */
    fun find(vmName: String): ByteArray? {
        if (vmName in found) return found[vmName]
        return locate(vmName).also { found[vmName] = it }
    }

    private fun locate(vmName: String): ByteArray? {
        val path = "$vmName.class"
        for (entry in entries) {
            if (entry.isDirectory) {
                val file = File(entry, path)
                if (file.isFile) return file.readBytes()
            } else {
                val zip = zipOf(entry) ?: continue
                val zipEntry = zip.getEntry(path) ?: continue
                return zip.getInputStream(zipEntry).use { it.readBytes() }
            }
        }
        return null
    }

    private fun zipOf(file: File): ZipFile? {
        if (file in jars) return jars[file]
        val zip = try {
            ZipFile(file)
        } catch (e: IOException) {
            null
        }
        jars[file] = zip
        return zip
    }

    override fun close() {
        jars.values.forEach { it?.close() }
        jars.clear()
    }
}

package id.tensky.coldspot.bundle

import java.util.TreeSet

/** Which compiled classes go with which changed file, which could not be placed, and which lines are blind. */
internal class Selection(
    /** Changed file → its classes that the change touches, by name. Files that got none are absent. */
    val classesByFile: Map<String, List<CompiledClass>>,
    /** Changed file → every class placed with it, touched by the change or not, by name: where its previews are looked for. */
    val classesOfFile: Map<String, List<CompiledClass>>,
    val ambiguous: List<AmbiguousClass>,
    /** Changed file → its changed lines that run only inside classes that cannot ship; see [blindLinesOf]. */
    val blindLinesByFile: Map<String, Set<Int>>,
)

/**
 * Attributes classes to changed files by `SourceFile` and `LineNumberTable` alone, never by deriving a class
 * name from a file name: that would miss lambdas, file facades, coroutine state machines and Compose synthetics.
 *
 * `SourceFile` is a bare file name, so the package is what places it: a class belongs to the changed file whose
 * path ends in `<package dir>/<SourceFile>`. Kotlin lets package and directory disagree, so when no changed file
 * ends that way, and no file in the work tree does either, the name alone decides, provided it decides: with
 * several changed files of that name the class is [Selection.ambiguous] and left out. If the package does point
 * at an existing file, the class is that unchanged file's and stays home.
 *
 * A class is kept only if the change touches lines it has. Without a `LineNumberTable` it could only add noise
 * and is dropped, as is a class the change does not touch under any candidate, which needs no placing at all.
 *
 * A class whose `SourceFile` the diff does not know at all is a library's, or, per Finding 4, a lambda that
 * Kotlin regenerated from a library's inline function and stamped with the library's file: `LazyDsl.kt` for
 * Compose's `items { }`. Such a class cannot ship, but its SMAP still says which changed lines it holds, and
 * those are the file's [Selection.blindLinesByFile].
 *
 * [sourceFiles] is every Kotlin and Java file in the work tree, consulted only when a package points away from
 * every changed file.
 */
internal fun selectClasses(
    changedLines: Map<String, Set<Int>>,
    classes: List<CompiledClass>,
    sourceFiles: Lazy<Set<String>>,
): Selection {
    val changed = ChangedFiles(changedLines, sourceFiles)
    val matched = HashMap<String, MutableList<CompiledClass>>()
    val placed = HashMap<String, MutableList<CompiledClass>>()
    val ambiguous = ArrayList<AmbiguousClass>()
    val blind = HashMap<String, TreeSet<Int>>()

    for (cls in classes) {
        val sourceFile = cls.sourceFile ?: continue
        if (cls.lines.isEmpty()) continue
        if (!changed.hasName(sourceFile)) {
            for ((file, lines) in blindLinesOf(cls, changed)) blind.getOrPut(file) { TreeSet() } += lines
            continue
        }

        val candidates = changed.candidatesFor(sourceFile, cls.packageDir)
        if (candidates.size == 1) placed.getOrPut(candidates.single()) { ArrayList() } += cls
        val touched = candidates.filter { file -> cls.lines.any { it in changedLines.getValue(file) } }
        when {
            touched.isEmpty() -> continue
            candidates.size == 1 -> matched.getOrPut(candidates.single()) { ArrayList() } += cls
            else -> ambiguous += AmbiguousClass(cls.name, sourceFile, candidates)
        }
    }
    return Selection(
        classesByFile = matched.mapValues { (_, list) -> list.sortedBy { it.name } }.toSortedMap(),
        classesOfFile = placed.mapValues { (_, list) -> list.sortedBy { it.name } }.toSortedMap(),
        ambiguous = ambiguous.sortedBy { it.className },
        blindLinesByFile = blind.toSortedMap(),
    )
}

/** The changed files, and where a source file that a class names sits among them. */
private class ChangedFiles(val lines: Map<String, Set<Int>>, private val sourceFiles: Lazy<Set<String>>) {
    private val byName = lines.keys.groupBy { it.substringAfterLast('/') }

    fun hasName(name: String): Boolean = name in byName

    /**
     * The changed files that a file called [name], compiled into package [packageDir], could be: those whose
     * path ends in `<packageDir>/<name>`; none, if a file in the work tree ends that way, since the class is
     * that unchanged file's; else every changed file of that name, Kotlin letting package and directory disagree.
     */
    fun candidatesFor(name: String, packageDir: String): List<String> {
        val sameName = byName[name] ?: return emptyList()
        val wherePackageSays = if (packageDir.isEmpty()) name else "$packageDir/$name"
        val byPackage = sameName.filter { it.endsWithPath(wherePackageSays) }
        if (byPackage.isNotEmpty()) return byPackage
        if (sourceFiles.value.any { it.endsWithPath(wherePackageSays) }) return emptyList()
        return sameName
    }
}

/**
 * The changed lines that [cls]'s code comes from, by its SMAP: each line number the class has is traced to the
 * file and line it was inlined from, that file is placed among the changed files by the same rules as a
 * `SourceFile` (several candidates: none, never a guess), and the line is kept if it is one of the file's
 * changed lines. Lines a shipped class also covers are kept too; the app decides what that means.
 */
private fun blindLinesOf(cls: CompiledClass, changed: ChangedFiles): Map<String, Set<Int>> {
    val smap = cls.parsedSmap ?: return emptyMap()

    val placed = HashMap<Int, String?>()
    val result = HashMap<String, TreeSet<Int>>()
    for (outputLine in cls.lines) {
        val source = smap.sourceOf(outputLine) ?: continue
        val file = placed.getOrPut(source.fileId) {
            smap.files[source.fileId]?.let { changed.candidatesFor(it.name, it.packageDir).singleOrNull() }
        } ?: continue
        if (source.line in changed.lines.getValue(file)) result.getOrPut(file) { TreeSet() } += source.line
    }
    return result
}

/** Whether the path ends with [tail] on a directory boundary: `lib/xcom/a/Utils.kt` does not end with `com/a/Utils.kt`. */
private fun String.endsWithPath(tail: String): Boolean = this == tail || endsWith("/$tail")

package id.tensky.coldspot.bundle

import org.objectweb.asm.AnnotationVisitor
import org.objectweb.asm.ClassReader
import org.objectweb.asm.ClassVisitor
import org.objectweb.asm.Label
import org.objectweb.asm.MethodVisitor
import org.objectweb.asm.Opcodes
import java.io.File
import java.util.TreeSet

/** A class file as the compiler left it: the attributes selection and preview detection rest on, and the bytes to ship. */
internal class CompiledClass(
    /** The VM name, e.g. `com/acme/FeedKt$lambda$1`. */
    val name: String,
    /** The `SourceFile` attribute, a bare file name such as `Feed.kt`; null when the compiler left it out. */
    val sourceFile: String?,
    /** The `SourceDebugExtension` attribute, kotlinc's SMAP (see [parseSmap]); null when there is none. */
    val smap: String?,
    /** Every line any method's `LineNumberTable` mentions; empty when no method has one. */
    val lines: Set<Int>,
    /** The class's own annotations, visible and invisible, as VM names (`androidx/compose/ui/tooling/preview/Preview`). */
    val annotations: List<String>,
    /** The superclass's VM name; null for `java/lang/Object` itself. */
    val superName: String?,
    /** The VM names of the interfaces the class declares. */
    val interfaces: List<String>,
    /** Every method, in class-file order. */
    val methods: List<CompiledMethod>,
    val bytes: ByteArray,
    val origin: File,
) {
    /** The package as a directory, `com/acme`; empty in the default package. */
    val packageDir: String get() = name.substringBeforeLast('/', "")

    /** The SMAP parsed, once; a class carrying one that cannot be read is an error naming the file. */
    val parsedSmap: Smap? by lazy {
        smap?.let { text ->
            try {
                parseSmap(text)
            } catch (e: IllegalArgumentException) {
                throw IllegalStateException("$origin: ${e.message}", e)
            }
        }
    }
}

/** One method of a [CompiledClass]: the lines its `LineNumberTable` mentions and the annotations on it, visible and invisible. */
internal class CompiledMethod(val name: String, val lines: Set<Int>, val annotations: List<String>)

/** What [readClasses] found: one [CompiledClass] per name, and the names it met compiled differently more than once. */
internal data class ReadClasses(val classes: List<CompiledClass>, val conflicts: List<ConflictingClass>)

/**
 * A class found in two class directories with different bytes: the build compiled it twice. Hilt's aggregating
 * task does that to the application's `_GeneratedInjector` after an incremental edit (its javac runs with
 * `-parameters`, KSP's without), and AGP appends its output to the module's classes all the same. The copy from
 * the first directory is the one the bundle reads and the transform ships; [dropped] is ignored.
 */
public data class ConflictingClass(
    /** The VM name. */
    public val className: String,
    /** The class file read: the first directory's. */
    public val kept: File,
    /** The class file ignored. */
    public val dropped: File,
)

/**
 * Every `.class` under [classDirs], in directory order, the first directory holding a name winning: the same
 * order the transform writes its jar in, so what the bundle reads is what the APK runs. A class compiled into
 * two of them is unremarkable while the bytes agree, and a [ReadClasses.conflicts] entry otherwise; whether
 * that matters is for the caller to decide, by whether the class is one it ships.
 */
internal fun readClasses(classDirs: List<File>): ReadClasses {
    val byName = LinkedHashMap<String, CompiledClass>()
    val conflicts = ArrayList<ConflictingClass>()
    for (dir in classDirs) {
        for (file in dir.walkTopDown().filter { it.isFile && it.extension == "class" }) {
            val cls = readClass(file)
            val first = byName.putIfAbsent(cls.name, cls) ?: continue
            if (!first.bytes.contentEquals(cls.bytes)) conflicts += ConflictingClass(cls.name, kept = first.origin, dropped = cls.origin)
        }
    }
    return ReadClasses(byName.values.toList(), conflicts)
}

private fun readClass(file: File): CompiledClass {
    val bytes = file.readBytes()
    var name = ""
    var superName: String? = null
    var interfaces = emptyList<String>()
    var sourceFile: String? = null
    var smap: String? = null
    val lines = TreeSet<Int>()
    val annotations = ArrayList<String>()
    val methods = ArrayList<CompiledMethod>()
    val reader = object : ClassVisitor(Opcodes.ASM9) {
        override fun visit(version: Int, access: Int, className: String, signature: String?, superClass: String?, itfs: Array<String>?) {
            name = className
            superName = superClass
            interfaces = itfs?.toList() ?: emptyList()
        }

        override fun visitSource(source: String?, debug: String?) {
            sourceFile = source
            smap = debug
        }

        override fun visitAnnotation(descriptor: String, visible: Boolean): AnnotationVisitor? {
            annotations += vmNameOf(descriptor)
            return null
        }

        override fun visitMethod(access: Int, methodName: String, descriptor: String, signature: String?, exceptions: Array<String>?): MethodVisitor {
            val methodLines = TreeSet<Int>()
            val methodAnnotations = ArrayList<String>()
            return object : MethodVisitor(Opcodes.ASM9) {
                override fun visitAnnotation(descriptor: String, visible: Boolean): AnnotationVisitor? {
                    methodAnnotations += vmNameOf(descriptor)
                    return null
                }

                override fun visitLineNumber(line: Int, start: Label) {
                    methodLines += line
                    lines += line
                }

                override fun visitEnd() {
                    methods += CompiledMethod(methodName, methodLines, methodAnnotations)
                }
            }
        }
    }
    ClassReader(bytes).accept(reader, ClassReader.SKIP_FRAMES)
    return CompiledClass(name, sourceFile, smap, lines, annotations, superName, interfaces, methods, bytes, file)
}

/** `Lcom/acme/Thing;` → `com/acme/Thing`. */
internal fun vmNameOf(descriptor: String): String = descriptor.removePrefix("L").removeSuffix(";")

package id.tensky.coldspot.bundle

/**
 * Which changed files are noise: not measured, but never dropped in silence either (the shared manifest lists
 * each with the rule that matched, see [Manifest.excluded]).
 *
 * Every pattern is an Ant-style glob matched against the whole work-tree-relative, `/`-separated path: `*` and
 * `?` stay within one path segment, `**` crosses segments, and a leading `**` followed by a slash matches at the
 * root as well as at any depth. [DEFAULT_PATTERNS] cover what a diff usually carries that the app never runs:
 * test source sets, test fixtures, and the build's own code.
 */
public class ExcludeRules(public val patterns: List<String>) {
    private val compiled: List<Pair<String, Regex>> = patterns.map { it to globToRegex(it) }

    /** The first of [patterns] that [path] matches, in the order given, or null when none does. */
    public fun matching(path: String): String? = compiled.firstOrNull { (_, regex) -> regex.matches(path) }?.first

    public companion object {
        /** Unit and instrumented tests, test fixtures, `buildSrc` and `build-logic`, at any depth. */
        public val DEFAULT_PATTERNS: List<String> = listOf(
            "**/src/test/**",
            "**/src/androidTest/**",
            "**/src/testFixtures/**",
            "**/buildSrc/**",
            "**/build-logic/**",
        )

        /** [DEFAULT_PATTERNS] alone. */
        public val DEFAULT: ExcludeRules = ExcludeRules(DEFAULT_PATTERNS)

        private fun globToRegex(glob: String): Regex {
            val regex = StringBuilder()
            var i = 0
            while (i < glob.length) {
                when {
                    glob.startsWith("**/", i) -> {
                        regex.append("(?:.*/)?")
                        i += 3
                    }
                    glob.startsWith("**", i) -> {
                        regex.append(".*")
                        i += 2
                    }
                    glob[i] == '*' -> {
                        regex.append("[^/]*")
                        i++
                    }
                    glob[i] == '?' -> {
                        regex.append("[^/]")
                        i++
                    }
                    else -> {
                        regex.append(Regex.escape(glob[i].toString()))
                        i++
                    }
                }
            }
            return Regex(regex.toString())
        }
    }
}

package id.tensky.coldspot.bundle

import id.tensky.coldspot.diff.BaseSource
import kotlinx.serialization.Serializable

/**
 * `coldspot/manifest.json`, written once per APK by the application module: everything about the change that
 * does not depend on which module compiled what. What each module shipped for it is in that module's own
 * [ModuleManifest], next to its class files; the app joins the two by file path.
 *
 * [SCHEMA_VERSION] moves when a reader of the previous shape would misread the new one.
 */
@Serializable
public data class Manifest(
    public val schemaVersion: Int,
    public val base: Base,
    public val head: Head,
    public val commits: Commits,
    /** The JaCoCo that instrumented the APK's changed classes: the app must analyse with the same, or its colours are wrong. */
    public val jacoco: Jacoco,
    /** Every changed source file the build measures, whether or not any module could attribute a class to it. */
    public val files: List<ChangedFile>,
    /** Every changed source file the build leaves out as noise, and why. Never dropped in silence. */
    public val excluded: List<ExcludedFile>,
) {
    /** What the working tree was compared with. */
    @Serializable
    public data class Base(
        /** The ref as given, or as the diff module chose it; [source] says which. */
        public val ref: String,
        /** The commit actually compared with: a branch's merge-base with HEAD, anything else as given. */
        public val sha: String,
        public val source: BaseSource,
    )

    @Serializable
    public data class Head(
        /** HEAD's commit, or null while HEAD is unborn. */
        public val sha: String?,
        /** Whether anything on disk differs from HEAD, sources or not: the APK is not HEAD's. */
        public val dirty: Boolean,
    )

    /** The commits in the build: HEAD's history back to, and excluding, [Base.sha], in `git log <base>..HEAD` order. */
    @Serializable
    public data class Commits(
        /** The newest 50 at most; [total] says how many there are in all, for a "+N more". */
        public val listed: List<Commit>,
        public val total: Int,
    )

    @Serializable
    public data class Commit(
        /** The first 7 characters of [sha]. */
        public val shortSha: String,
        public val sha: String,
        /** The first line of the commit message. */
        public val summary: String,
    )

    /**
     * The JaCoCo whose `Instrumenter` placed the probes. Probe placement and class ids must agree between it and
     * the `Analyzer` on the device, so the build forces this version onto the coverage runtime classpath and the
     * app compares [build] with the `JaCoCo.VERSION` of the jacoco-core it runs, showing an error rather than
     * colours when they differ.
     */
    @Serializable
    public data class Jacoco(
        /** The Maven version of jacoco-core, `0.8.14`: the coordinate the runtime classpath is forced to. */
        public val version: String,
        /** `org.jacoco.core.JaCoCo.VERSION` of that jacoco-core, the qualified build string, `0.8.14.202510111229`. */
        public val build: String,
    )

    @Serializable
    public data class ChangedFile(
        /** Relative to the work tree root, `/`-separated. */
        public val path: String,
        /** 1-based and ascending, in the working-tree version of the file. */
        public val changedLines: List<Int>,
        /** The whole file, as it is on disk. Here and nowhere else: module manifests carry no text. */
        public val text: String,
    )

    /** A changed file an exclude rule matched: not measured, listed so that the app can say so. */
    @Serializable
    public data class ExcludedFile(
        public val path: String,
        /** How many lines the change touched, for a "12 lines, excluded". */
        public val changedLines: Int,
        /** The pattern that matched, as written in the rules; see [ExcludeRules]. */
        public val rule: String,
    )

    public companion object {
        /**
         * 2: `blindLines` added. 3: [commits] added. 4: one manifest per APK plus one per module: the file text
         * and [excluded] live here, the classes and blind lines in [ModuleManifest]. 5: [ModuleManifest.ModuleFile.previews].
         * 6: [jacoco].
         */
        public const val SCHEMA_VERSION: Int = 6
    }
}

/**
 * `coldspot/<module>/manifest.json`, written by every module the plugin is applied to: which of its compiled
 * classes shipped for which changed file, which changed lines only its unshippable classes hold, and which
 * changed lines are previews. Nothing about the change itself, and no file text: that is the application's
 * [Manifest], once per APK.
 */
@Serializable
public data class ModuleManifest(
    public val schemaVersion: Int,
    /** The module's project path as a folder, `feature/foryou/impl`; the folder this manifest sits in. */
    public val module: String,
    /** Only the changed files this module has something for; in path order. */
    public val files: List<ModuleFile>,
) {
    @Serializable
    public data class ModuleFile(
        /** As in [Manifest.ChangedFile.path]. */
        public val path: String,
        /** VM names (`com/acme/FeedKt$lambda$1`) of the classes shipped for this file, ascending. */
        public val classes: List<String>,
        /**
         * Changed lines that run only inside classes this module cannot ship: lambdas Kotlin regenerated from
         * a library's inline function and stamped with the library's file (Finding 4). Their probes fire, but
         * JaCoCo maps no line to them, so a line here must never show as red; amber at most. Ascending, and
         * possibly covered by one of [classes] as well.
         */
        public val blindLines: List<Int>,
        /**
         * Changed lines that belong to Compose previews, which never run in the app: neutral, never red, and
         * shown with the reason. Each entry is one preview's lines; in line order, no line twice.
         */
        public val previews: List<PreviewLines>,
    )

    /** The changed lines one preview holds (its `@Preview` function, or a `PreviewParameterProvider` class), and which. */
    @Serializable
    public data class PreviewLines(
        /** Ascending. */
        public val lines: List<Int>,
        /** `@Preview on GreetingPreview`, `@DevicePreviews on ForYouScreenLoading (@Preview via @DevicePreviews)`, `Names implements PreviewParameterProvider`. */
        public val reason: String,
    )
}

package id.tensky.coldspot.bundle

import org.objectweb.asm.AnnotationVisitor
import org.objectweb.asm.ClassReader
import org.objectweb.asm.ClassVisitor
import org.objectweb.asm.Opcodes

/**
 * Compose previews never run in the app, so their lines would stay red for ever: they are neutral, and the
 * manifest says why. This finds them in a file's compiled classes.
 *
 * A method is a preview when it carries `@Preview` (or `@Preview.Container`, several of them) itself, or any
 * annotation whose class is, through any number of steps, annotated with one: a multipreview such as NiA's
 * `@DevicePreviews`. Annotation classes are found among the module's own classes first, then on the compile
 * classpath, since a team's multipreviews live in a shared module. Both visible and invisible annotations
 * count: `@Preview` has binary retention, multipreviews usually runtime. Only annotations actually met on a
 * method are resolved, each once, and a cycle among annotation classes is cut rather than followed.
 *
 * A preview's lines are its method's own, first to last, from the `LineNumberTable` with inlined code
 * left out by the SMAP: everything lexically inside, lambdas included, whichever class they compiled into.
 * A class implementing `PreviewParameterProvider`, directly or through its supertypes, is preview-only too,
 * over its own lines.
 */
internal class PreviewFinder(private val own: Map<String, CompiledClass>, private val classpath: ClassLookup) {
    private val summaries = HashMap<String, ClassSummary?>()
    private val chains = HashMap<String, List<String>?>()
    private val providers = HashMap<String, Boolean>()

    /** The preview ranges of [cls], in line order: each method's, then the class's own if it is a parameter provider. */
    fun previewRangesOf(cls: CompiledClass): List<PreviewRange> {
        val ranges = ArrayList<PreviewRange>()
        for (method in cls.methods) {
            val chain = method.annotations.firstNotNullOfOrNull { annotation -> chainOf(annotation, emptySet())?.let { annotation to it } } ?: continue
            val lines = ownLines(cls, method.lines)
            if (lines.isEmpty()) continue
            val (annotation, via) = chain
            val reason = if (via.isEmpty()) "@Preview on ${method.name}" else "@${simpleName(annotation)} on ${method.name} (@Preview via ${via.joinToString { "@" + simpleName(it) }})"
            ranges += PreviewRange(lines.min()..lines.max(), reason)
        }
        if (implementsProvider(cls.name, emptySet())) {
            val lines = ownLines(cls, cls.lines)
            if (lines.isNotEmpty()) ranges += PreviewRange(lines.min()..lines.max(), "${simpleName(cls.name)} implements PreviewParameterProvider")
        }
        return ranges.sortedBy { it.lines.first }
    }

    /**
     * The multipreview annotations from [annotation] down to the one carrying `@Preview`, empty when [annotation]
     * is `@Preview` itself; null when it leads to no preview. Remembered once known for sure: a verdict reached
     * only by cutting a cycle is not, so that the other way round the cycle can still be found.
     */
    private fun chainOf(annotation: String, visiting: Set<String>): List<String>? {
        if (annotation == PREVIEW || annotation == PREVIEW_CONTAINER) return emptyList()
        if (annotation in chains) return chains[annotation]
        if (annotation in visiting) return null // a cycle: cut here, and not remembered
        val summary = summaryOf(annotation)
        if (summary == null) {
            chains[annotation] = null // not on the classpath: nothing to follow
            return null
        }
        var definite = true
        for (meta in summary.annotations) {
            val below = chainOf(meta, visiting + annotation)
            if (below != null) return (listOf(annotation) + below).also { chains[annotation] = it }
            if (meta !in chains) definite = false // its null came from a cut cycle
        }
        if (definite) chains[annotation] = null
        return null
    }

    private fun implementsProvider(className: String, visiting: Set<String>): Boolean {
        providers[className]?.let { return it }
        if (className in visiting) return false
        val summary = summaryOf(className) ?: return false.also { providers[className] = false }
        val supertypes = summary.interfaces + listOfNotNull(summary.superName)
        val result = PREVIEW_PARAMETER_PROVIDER in supertypes || supertypes.any { implementsProvider(it, visiting + className) }
        providers[className] = result
        return result
    }

    private fun summaryOf(className: String): ClassSummary? {
        if (className in summaries) return summaries[className]
        val summary = own[className]?.let { ClassSummary(it.annotations, it.superName, it.interfaces) }
            ?: classpath.find(className)?.let(::summarise)
        summaries[className] = summary
        return summary
    }

    /**
     * [lines] that are the class's own source lines: with an SMAP, those it maps to the same line of the class's
     * own file, which leaves out code inlined from elsewhere, numbered past the end of the file; without one, all.
     */
    private fun ownLines(cls: CompiledClass, lines: Set<Int>): Set<Int> {
        val smap = cls.parsedSmap ?: return lines
        return lines.filterTo(LinkedHashSet()) { line ->
            val source = smap.sourceOf(line) ?: return@filterTo true
            source.line == line && smap.files[source.fileId]?.name == cls.sourceFile
        }
    }

    private fun simpleName(vmName: String): String = vmName.substringAfterLast('/').substringAfterLast('$')

    private companion object {
        const val PREVIEW = "androidx/compose/ui/tooling/preview/Preview"
        const val PREVIEW_CONTAINER = "androidx/compose/ui/tooling/preview/Preview\$Container"
        const val PREVIEW_PARAMETER_PROVIDER = "androidx/compose/ui/tooling/preview/PreviewParameterProvider"
    }
}

/** Lines of a changed file that a preview holds, first to last, and the preview that does. */
internal class PreviewRange(val lines: IntRange, val reason: String)

/** What preview detection needs of a class it does not ship: its annotations and supertypes. */
private class ClassSummary(val annotations: List<String>, val superName: String?, val interfaces: List<String>)

private fun summarise(bytes: ByteArray): ClassSummary {
    val annotations = ArrayList<String>()
    var superName: String? = null
    var interfaces = emptyList<String>()
    val reader = object : ClassVisitor(Opcodes.ASM9) {
        override fun visit(version: Int, access: Int, name: String, signature: String?, superClass: String?, itfs: Array<String>?) {
            superName = superClass
            interfaces = itfs?.toList() ?: emptyList()
        }

        override fun visitAnnotation(descriptor: String, visible: Boolean): AnnotationVisitor? {
            annotations += vmNameOf(descriptor)
            return null
        }
    }
    ClassReader(bytes).accept(reader, ClassReader.SKIP_CODE or ClassReader.SKIP_DEBUG or ClassReader.SKIP_FRAMES)
    return ClassSummary(annotations, superName, interfaces)
}

package id.tensky.coldspot.bundle

import id.tensky.coldspot.diff.hasUncommittedChanges
import id.tensky.coldspot.diff.workingTreeDiff
import java.io.File
import java.io.IOException
import java.nio.file.Files

/**
 * Everything a build learns from git, once: the diff, what it was measured between, and the source files of the
 * work tree. Every module's bundle is cut from the same instance (the plugin keeps one per build in a shared
 * service), so the repository is opened, diffed and scanned once, however many modules there are. Immutable,
 * and safe to read from several tasks at a time.
 *
 * [changedLines] holds every changed file, noise included: which of them are excluded is a per-module question
 * answered by [ExcludeRules] when the bundle is cut, see [buildBundle].
 */
public class RepositoryChanges(
    /** The root of the working tree; every path here is relative to it, `/`-separated. */
    public val workTree: File,
    public val base: Manifest.Base,
    public val head: Manifest.Head,
    public val commits: Manifest.Commits,
    /** As the diff module reports them: changed file to its changed lines, both ascending. */
    public val changedLines: Map<String, Set<Int>>,
) {
    /**
     * Every Kotlin and Java file under [workTree], `.git` and symlinks left alone. Consulted by class selection
     * only when a class's package points away from every changed file, hence walked on first use, and once.
     */
    public val sourceFiles: Set<String> by lazy {
        workTree.walkTopDown()
            .onEnter { it.name != ".git" && !Files.isSymbolicLink(it.toPath()) }
            .filter { it.isFile && (it.extension == "kt" || it.extension == "java") }
            .mapTo(HashSet()) { it.relativeTo(workTree).invariantSeparatorsPath }
    }

    public companion object {
        /**
         * Diffs the working tree of the repository containing [repoDir] against [baseRef], or against the base the
         * diff module chooses when that is null (`origin/HEAD`, then `origin/main`, then `origin/master`; never a
         * local branch), and asks it whether anything on disk differs from HEAD.
         *
         * @throws IllegalArgumentException for whatever the diff module refuses, including no base at all
         * @throws IOException when the repository or a changed source file cannot be read
         */
        @Throws(IOException::class)
        public fun of(repoDir: File, baseRef: String?): RepositoryChanges {
            val diff = workingTreeDiff(repoDir, baseRef)
            return RepositoryChanges(
                workTree = diff.workTree,
                base = Manifest.Base(diff.base.ref, diff.base.commit, diff.base.source),
                head = Manifest.Head(sha = diff.headCommit, dirty = hasUncommittedChanges(repoDir)),
                commits = Manifest.Commits(diff.commits.listed.map { Manifest.Commit(it.shortSha, it.sha, it.summary) }, diff.commits.total),
                changedLines = diff.changedLines,
            )
        }
    }
}

package id.tensky.coldspot.bundle.tools

import id.tensky.coldspot.bundle.ExcludeRules
import id.tensky.coldspot.bundle.Manifest
import id.tensky.coldspot.bundle.RepositoryChanges
import id.tensky.coldspot.bundle.buildBundle
import java.io.File
import kotlin.system.exitProcess

/**
 * Builds a bundle by hand and prints what went into it, for checking the module against a real repository:
 *
 *     ./gradlew :tooling:bundle:printBundle -q -Pclasses=<dir>[,<dir>] [-Pclasspath=<jar or dir>[,...]] [-Pdir=<repo>] [-Pbase=<ref>] [-Pout=<dir>]
 *
 * [args] are the repository, the base ref (empty to let the module choose), the class directories separated
 * by commas, the output directory, and the compile classpath entries separated by commas (empty for none: then
 * only the module's own annotations tell previews), in that order. The bundle is cut as an application module's
 * would be, under `<out>/coldspot/`: the shared manifest plus a module folder called `root`, with the default
 * excludes.
 */
public fun main(args: Array<String>) {
    val classDirs = args[2].split(',').filter { it.isNotBlank() }.map(::File)
    if (classDirs.isEmpty()) {
        System.err.println("pass -Pclasses=<compile output dir>[,<dir>], e.g. app/build/tmp/kotlin-classes/debug")
        exitProcess(2)
    }
    val coldspotDir = File(args[3], "coldspot")
    val classpath = args.getOrElse(4) { "" }.split(',').filter { it.isNotBlank() }.map(::File)

    val changes = RepositoryChanges.of(File(args[0]), args[1].ifEmpty { null })
    // No instrumenter here, so no JaCoCo to name: the plugin fills this in from the jacoco-core it instruments with.
    val report = buildBundle(changes, ExcludeRules.DEFAULT, "root", classDirs, classpath, coldspotDir, sharedManifest = true, Manifest.Jacoco("none", "none"))

    for ((file, classes) in report.classesByFile) println("$file: $classes")
    for (file in report.filesWithoutClasses) println("$file: no class matched")
    for ((file, lines) in report.blindLinesByFile) println("$file: blind $lines")
    for ((file, previews) in report.previewLinesByFile) for (it in previews) println("$file: preview ${it.lines} (${it.reason})")
    for (it in report.ambiguous) println("ambiguous: ${it.className} (${it.sourceFile}) could be any of ${it.candidates}")
    for (it in report.excluded) println("excluded: ${it.path} (${it.changedLines} lines) by ${it.rule}")
    for (it in report.conflicts) println("compiled twice: ${it.className}, read from ${it.kept}, not ${it.dropped}")
    println("-> ${File(coldspotDir, "manifest.json")}, ${report.classesByFile.values.sumOf { it.size }} class files under root/classes")
}

package id.tensky.coldspot.plugin

import org.gradle.api.DefaultTask
import org.gradle.api.file.DirectoryProperty
import org.gradle.api.tasks.OutputDirectory
import org.gradle.api.tasks.TaskAction
import org.gradle.work.DisableCachingByDefault

/**
 * Writes the `jacoco-agent.properties` the APK must carry for offline instrumentation: JaCoCo's runtime reads it
 * from the classpath when the first probe fires, and without it opens `jacoco.exec` in the working directory,
 * which on Android is `/` and read-only, so the very first instrumented class fails to initialise. `output=none`
 * keeps the execution data in memory, where the app reads it through the agent's API (FINDINGS Finding 1).
 * AGP's own coverage does the same (`JacocoPropertiesTask`).
 */
@DisableCachingByDefault(because = "A few bytes; writing them is cheaper than a cache lookup")
public abstract class ColdSpotAgentPropertiesTask : DefaultTask() {
    /** A generated Java resources root holding `jacoco-agent.properties`. */
    @get:OutputDirectory
    public abstract val outputDir: DirectoryProperty

    @TaskAction
    public fun write() {
        val root = outputDir.get().asFile
        root.deleteRecursively()
        root.mkdirs()
        root.resolve("jacoco-agent.properties").writeText("output=none\n")
    }
}

package id.tensky.coldspot.plugin

import id.tensky.coldspot.bundle.ExcludeRules
import id.tensky.coldspot.bundle.Manifest
import id.tensky.coldspot.bundle.buildBundle
import org.gradle.api.DefaultTask
import org.gradle.api.file.ConfigurableFileCollection
import org.gradle.api.file.Directory
import org.gradle.api.file.DirectoryProperty
import org.gradle.api.file.RegularFile
import org.gradle.api.file.RegularFileProperty
import org.gradle.api.provider.ListProperty
import org.gradle.api.provider.Property
import org.gradle.api.services.ServiceReference
import org.gradle.api.tasks.Classpath
import org.gradle.api.tasks.Input
import org.gradle.api.tasks.InputFiles
import org.gradle.api.tasks.Internal
import org.gradle.api.tasks.Optional
import org.gradle.api.tasks.OutputDirectory
import org.gradle.api.tasks.OutputFile
import org.gradle.api.tasks.PathSensitive
import org.gradle.api.tasks.PathSensitivity
import org.gradle.api.tasks.TaskAction
import org.gradle.work.DisableCachingByDefault
import org.jacoco.core.instr.Instrumenter
import org.jacoco.core.runtime.OfflineInstrumentationAccessGenerator
import java.io.File
import java.util.TreeMap
import java.util.zip.ZipEntry
import java.util.zip.ZipFile
import java.util.zip.ZipOutputStream

/**
 * The transform of a module's own classes for one variant, and the bundle the app reads at run time.
 *
 * What changed comes from the build's one [ColdSpotDiffService], which diffs the working tree against the base
 * once for every module; this task only scans its own classes and lets the bundle select the ones the change
 * touches. Those come out of [transformedJar] instrumented by JaCoCo's [Instrumenter] (offline access, as AGP's
 * own coverage would do), every other class and file unchanged. The selected classes' input bytes B, exactly
 * what the instrumenter read, ship as generated assets: `coldspot/<module>/manifest.json` and
 * `coldspot/<module>/classes/<vm/Name>.class` under [outputDir], and, in the application module alone,
 * `coldspot/manifest.json` describing the change as a whole ([sharedManifest]).
 *
 * The task always runs: what changed is a question for git, and Gradle cannot know when git's answer changes.
 * Its outputs are deterministic (no timestamps, entries in name order, bytes copied as they are), so when nothing
 * changed since the last build the tasks downstream, from dexing to packaging, stay up to date.
 *
 * All git work happens at execution time, in the service, never while the build is being configured.
 */
@DisableCachingByDefault(because = "The result depends on the git working tree, which Gradle cannot see")
public abstract class ColdSpotBundleTask : DefaultTask() {
    /** The build's diff, shared with every other module's task; see [ColdSpotDiffService]. */
    @get:ServiceReference(ColdSpotDiffService.NAME)
    public abstract val diffService: Property<ColdSpotDiffService>

    /** A directory inside the repository, the build's root; the work tree is found from it. Not an input: git state is what is always re-read. */
    @get:Internal
    public abstract val repoDir: DirectoryProperty

    /** The base ref, or absent to let the diff module choose one; see [ColdSpotExtension.effectiveBaseRef]. */
    @get:Input
    @get:Optional
    public abstract val baseRef: Property<String>

    /** Where under `assets/coldspot/` this module's bundle goes: its project path as a folder. */
    @get:Input
    public abstract val moduleFolder: Property<String>

    /** The exclude patterns, defaults included; see [ColdSpotExtension.excludes]. */
    @get:Input
    public abstract val excludes: ListProperty<String>

    /** Whether this task also writes `coldspot/manifest.json`, the one manifest of the whole change: the application module's does. */
    @get:Input
    public abstract val sharedManifest: Property<Boolean>

    /** The Maven version of the JaCoCo whose instrumenter this task uses, `0.8.14`; see [Manifest.Jacoco]. */
    @get:Input
    public abstract val jacocoVersion: Property<String>

    /** `JaCoCo.VERSION` of that JaCoCo, the qualified build string the app compares with its own jacoco-core's. */
    @get:Input
    public abstract val jacocoBuild: Property<String>

    /** The module's classes as directories, as AGP hands them to a transform. */
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    public abstract val classDirs: ListProperty<Directory>

    /** The module's classes as jars (the R class, an earlier transform's output). */
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    public abstract val classJars: ListProperty<RegularFile>

    /**
     * The variant's compile classpath, where the bundle looks up annotation classes and supertypes the module
     * does not hold, to tell previews: a team's multipreview annotation lives in a shared module.
     */
    @get:Classpath
    public abstract val compileClasspath: ConfigurableFileCollection

    /** Every input class and file, the selected classes instrumented: what the rest of the build sees as the module's classes. */
    @get:OutputFile
    public abstract val transformedJar: RegularFileProperty

    /** The generated assets root; the bundle goes into its `coldspot/` folder. */
    @get:OutputDirectory
    public abstract val outputDir: DirectoryProperty

    init {
        outputs.upToDateWhen { false }
    }

    @TaskAction
    public fun bundle() {
        val changes = diffService.get().changes(repoDir.get().asFile, baseRef.orNull)

        // Jars are unpacked so that the bundle's selection and the transform see one shape of input.
        val unpacked = temporaryDir.resolve("jars").also { it.deleteRecursively() }
        val dirs = classDirs.get().map { it.asFile } + classJars.get().mapIndexed { i, jar -> unpack(jar.asFile, unpacked.resolve(i.toString())) }

        val root = outputDir.get().asFile
        root.deleteRecursively()
        val report = buildBundle(
            changes, ExcludeRules(excludes.get()), moduleFolder.get(), dirs, compileClasspath.files.toList(), root.resolve(ASSETS_FOLDER),
            sharedManifest.get(), Manifest.Jacoco(jacocoVersion.get(), jacocoBuild.get()),
        )
        val selected = report.classesByFile.values.flatten().toHashSet()

        writeTransformedJar(transformedJar.get().asFile, dirs, selected)
        for (conflict in report.conflicts) {
            logger.info("ColdSpot: ${conflict.className} is compiled differently in ${conflict.kept} and ${conflict.dropped}; the first is what the build uses")
        }
        logger.info(
            "ColdSpot: ${selected.size} classes instrumented and bundled for ${report.classesByFile.size} changed files; " +
                "${report.filesWithoutClasses.size} changed files without a class here, ${report.ambiguous.size} ambiguous classes left out, " +
                "${report.excluded.size} changed files excluded, preview lines in ${report.previewLinesByFile.size} files, " +
                "${report.conflicts.size} classes compiled twice",
        )
    }

    private fun unpack(jar: File, into: File): File {
        ZipFile(jar).use { zip ->
            for (entry in zip.entries().asSequence().filterNot { it.isDirectory }) {
                val target = into.resolve(entry.name)
                check(target.canonicalPath.startsWith(into.canonicalPath + File.separator)) { "$jar: entry ${entry.name} escapes its directory" }
                target.parentFile.mkdirs()
                zip.getInputStream(entry).use { it.copyTo(target.outputStream()) }
            }
        }
        return into
    }

    /**
     * Every file of [dirs], by name order, the first occurrence of a path winning, as the bundle read them; [selected]
     * classes instrumented.
     */
    private fun writeTransformedJar(jar: File, dirs: List<File>, selected: Set<String>) {
        val files = TreeMap<String, File>()
        for (dir in dirs) {
            dir.walkTopDown().filter { it.isFile }.forEach { file -> files.putIfAbsent(file.relativeTo(dir).invariantSeparatorsPath, file) }
        }
        val instrumenter = Instrumenter(OfflineInstrumentationAccessGenerator())
        jar.parentFile.mkdirs()
        ZipOutputStream(jar.outputStream().buffered()).use { out ->
            for ((path, file) in files) {
                val bytes = file.readBytes()
                val vmName = path.removeSuffix(CLASS_SUFFIX)
                val content = if (path.endsWith(CLASS_SUFFIX) && vmName in selected) instrumenter.instrument(bytes, vmName) else bytes
                out.putNextEntry(ZipEntry(path).apply { time = FIXED_ENTRY_TIME })
                out.write(content)
                out.closeEntry()
            }
        }
    }

    public companion object {
        /** The folder under `assets/` that holds every module's bundle and the shared manifest. */
        public const val ASSETS_FOLDER: String = "coldspot"

        private const val CLASS_SUFFIX = ".class"

        /** 1980-01-01, the earliest a zip entry can carry: the output must not change with the clock. */
        private const val FIXED_ENTRY_TIME: Long = 315_532_800_000L
    }
}

package id.tensky.coldspot.plugin

import id.tensky.coldspot.bundle.RepositoryChanges
import org.gradle.api.logging.Logging
import org.gradle.api.services.BuildService
import org.gradle.api.services.BuildServiceParameters
import java.io.File
import java.util.concurrent.ConcurrentHashMap

/**
 * The one place a build asks git what changed. Every module's bundle task holds a reference to this service and
 * asks it for the [RepositoryChanges] of its repository and base; the first task to ask pays for the diff, the
 * others get the same instance back. A build service lives for one build invocation, so the next build asks git
 * afresh, as it must: Gradle cannot see the working tree change.
 *
 * Keyed by repository and base ref, so that modules disagreeing on `coldSpot { baseRef }` each get what they
 * asked for rather than whichever asked first. In practice the key is one.
 */
public abstract class ColdSpotDiffService : BuildService<BuildServiceParameters.None> {
    private val changes = ConcurrentHashMap<Key, RepositoryChanges>()

    /** The changes of the repository containing [repoDir] against [baseRef] (null: the diff module's choice), computed once. */
    public fun changes(repoDir: File, baseRef: String?): RepositoryChanges =
        changes.computeIfAbsent(Key(repoDir.canonicalPath, baseRef)) {
            RepositoryChanges.of(repoDir, baseRef).also {
                LOGGER.info("ColdSpot: diffed ${it.workTree} against ${it.base.ref} (${it.base.sha.take(7)}): ${it.changedLines.size} changed files")
            }
        }

    private data class Key(val repoDir: String, val baseRef: String?)

    public companion object {
        /** The name the service is registered under, for `@ServiceReference`. */
        public const val NAME: String = "coldSpotDiff"

        private val LOGGER = Logging.getLogger(ColdSpotDiffService::class.java)
    }
}

package id.tensky.coldspot.plugin

import id.tensky.coldspot.bundle.ExcludeRules
import org.gradle.api.provider.ListProperty
import org.gradle.api.provider.Property
import org.gradle.api.provider.Provider
import org.gradle.api.provider.ProviderFactory
import javax.inject.Inject

/** The `coldSpot { }` block of a module's build script, or of the convention plugin that applies ColdSpot to every module. */
public abstract class ColdSpotExtension @Inject constructor(providers: ProviderFactory) {
    /**
     * The git ref the working tree is diffed from: a branch (compared from its merge-base with HEAD), a tag, a SHA.
     * Optional: left unset, the diff module chooses `origin/HEAD`, then `origin/main`, then `origin/master`, and
     * fails naming this setting when the repository has none of them. `-Pcoldspot.base=<ref>` on the command line
     * overrides whatever is set here; see [effectiveBaseRef].
     */
    public abstract val baseRef: Property<String>

    /**
     * The build type ColdSpot instruments and ships its bundle with. Created from `debug` when the module has no
     * build type of that name; must be debuggable either way. Default `coverage`.
     */
    public abstract val buildTypeName: Property<String>

    /**
     * An application ID suffix for the coverage build type ColdSpot creates. Unset by default: the coverage build
     * then carries debug's application ID, and everything keyed on it (Firebase, Sign-In, Maps keys, push) keeps
     * working. Set it to install coverage builds next to debug ones. It cannot be combined with a build type the
     * module defines itself: that build type's own settings stand, and the build says so.
     */
    public abstract val applicationIdSuffix: Property<String>

    /**
     * Changed files that are noise, as Ant-style globs over work-tree-relative paths (`**` crosses directories, a
     * leading `**` matches at any depth). Defaults to [ExcludeRules.DEFAULT_PATTERNS]: test source sets, test
     * fixtures, `buildSrc`, `build-logic`. [exclude] adds to them; setting the property replaces them. An excluded
     * changed file is not measured, but the manifest lists it with the rule that matched, so nothing disappears.
     */
    public abstract val excludes: ListProperty<String>

    /** Adds [patterns] to [excludes]. */
    public fun exclude(vararg patterns: String) {
        excludes.addAll(*patterns)
    }

    /** What the build actually diffs from: `-Pcoldspot.base` when given, otherwise [baseRef]; absent when neither is set. */
    public val effectiveBaseRef: Provider<String> = providers.gradleProperty(BASE_PROPERTY).orElse(baseRef)

    private companion object {
        const val BASE_PROPERTY = "coldspot.base"
    }
}

package id.tensky.coldspot.plugin

import com.android.build.api.artifact.ScopedArtifact
import com.android.build.api.dsl.ApplicationExtension
import com.android.build.api.dsl.BuildType
import com.android.build.api.dsl.LibraryExtension
import com.android.build.api.dsl.TestedExtension
import com.android.build.api.variant.ApplicationAndroidComponentsExtension
import com.android.build.api.variant.LibraryAndroidComponentsExtension
import com.android.build.api.variant.ScopedArtifacts
import com.android.build.api.variant.Variant
import id.tensky.coldspot.bundle.ExcludeRules
import org.gradle.api.GradleException
import org.gradle.api.NamedDomainObjectContainer
import org.gradle.api.Plugin
import org.gradle.api.Project
import org.gradle.api.artifacts.Configuration
import org.jacoco.core.JaCoCo

/**
 * `io.github.tensky.coldspot`: prepares an Android module for ColdSpot. Applied to the application and to every
 * library module whose changed classes should be measured (decision C1: instrumentation is per module), normally
 * from the team's convention plugin.
 *
 * In an application or library module, the build type named by [ColdSpotExtension.buildTypeName] (`coverage`
 * by default) is made ready once the module's own `android {}` block has run: created from `debug` when the
 * module has none of that name, used as it is otherwise. Coverage is debug plus ColdSpot: a created build type
 * keeps debug's application ID (an application's, with debug's suffix; [ColdSpotExtension.applicationIdSuffix]
 * opts into another), and its dependency configurations extend debug's, so `debugImplementation`, `kspDebug`
 * and the like reach the coverage variant too. In every module the build type falls back to `debug` when a
 * dependency has no build type of that name, so leaving a module out of ColdSpot never breaks the modules that
 * depend on it. AGP's own coverage stays off in the build type ColdSpot creates: ColdSpot instruments what it
 * selects itself, so `testBuildType` is not touched and nobody's instrumented tests change. A build type the
 * module defines keeps its own settings; the one combination that cannot work, AGP's coverage on in the
 * `testBuildType`, is refused with the ways out. Release build types are never touched.
 *
 * Every variant of that build type gets a [ColdSpotBundleTask], `coldSpotBundle<Variant>`, registered as the
 * transform of the module's own classes (`ScopedArtifact.CLASSES`, PROJECT scope): the classes the bundle
 * selects come out instrumented with JaCoCo, every other class unchanged, and the selected classes' input bytes
 * ship as generated assets under `assets/coldspot/<module path>/`, so that modules never collide. The diff
 * itself is made once per build by the shared [ColdSpotDiffService]; each module's task only scans its own
 * classes, with the variant's compile classpath at hand to recognise previews by annotations another module
 * defines. The application module's task also writes `assets/coldspot/manifest.json`, the one description of
 * the change. Registered from the variant API, the transform runs before any `AsmClassVisitorFactory` (Hilt's
 * included), which AGP applies afterwards to its output. An application's coverage variant also gets JaCoCo's
 * agent runtime and core, at the exact version the instrumenter is, forced onto its runtime classpath and named
 * in the shared manifest, so that the analyser on the device is the instrumenter's twin, or says it is not.
 *
 * ColdSpot is debug-only tooling: it ships class files and reads JaCoCo's agent inside the running app. An
 * application build type that is not debuggable is refused while the build is being configured, before it is
 * changed. On a project that is neither an application nor a library, only the `coldSpot` extension exists.
 */
public class ColdSpotPlugin : Plugin<Project> {
    override fun apply(project: Project) {
        val extension = project.extensions.create(EXTENSION_NAME, ColdSpotExtension::class.java)
        extension.buildTypeName.convention(DEFAULT_BUILD_TYPE)
        extension.excludes.convention(ExcludeRules.DEFAULT_PATTERNS)
        // One per build, whichever module registers it first; the tasks find it by name.
        project.gradle.sharedServices.registerIfAbsent(ColdSpotDiffService.NAME, ColdSpotDiffService::class.java) {}

        project.pluginManager.withPlugin(ANDROID_APPLICATION) {
            val components = project.extensions.getByType(ApplicationAndroidComponentsExtension::class.java)
            // After the module's build script has had its say, before AGP locks the DSL: the one moment a plugin
            // may still add a build type.
            components.finalizeDsl { android ->
                val name = extension.buildTypeName.get()
                prepareApplicationBuildType(android, name, extension.applicationIdSuffix.orNull)
                extendDebugConfigurations(project, name)
            }
            project.afterEvaluate { extendDebugConfigurationsOnceMore(project, extension.buildTypeName.get()) }
            // Not a selector on the build type: its name is not final while this plugin is being applied.
            components.onVariants(components.selector().all()) { variant ->
                if (variant.buildType != extension.buildTypeName.get()) return@onVariants
                registerBundleTask(project, variant, extension, sharedManifest = true)
                addJacocoRuntime(project, variant)
                addAgentProperties(project, variant)
            }
        }
        project.pluginManager.withPlugin(ANDROID_LIBRARY) {
            val components = project.extensions.getByType(LibraryAndroidComponentsExtension::class.java)
            components.finalizeDsl { android ->
                val name = extension.buildTypeName.get()
                prepareBuildType(android, android.buildTypes, name)
                extendDebugConfigurations(project, name)
            }
            project.afterEvaluate { extendDebugConfigurationsOnceMore(project, extension.buildTypeName.get()) }
            components.onVariants(components.selector().all()) { variant ->
                if (variant.buildType == extension.buildTypeName.get()) registerBundleTask(project, variant, extension, sharedManifest = false)
            }
        }
    }

    private fun prepareApplicationBuildType(android: ApplicationExtension, name: String, applicationIdSuffix: String?) {
        val (buildType, created) = prepareBuildType(android, android.buildTypes, name)
        if (!buildType.isDebuggable) {
            throw GradleException(
                "ColdSpot: build type '$name' is not debuggable. ColdSpot is debug-only tooling (it ships class files and " +
                    "reads JaCoCo's agent inside the app), so its build type needs isDebuggable = true. Make '$name' " +
                    "debuggable, or point coldSpot { buildTypeName = \"...\" } at a build type that is.",
            )
        }
        when {
            !created -> if (applicationIdSuffix != null) {
                throw GradleException(
                    "ColdSpot: coldSpot { applicationIdSuffix = \"$applicationIdSuffix\" } cannot apply: build type '$name' is " +
                        "defined by this module, and ColdSpot never overrides a build type it did not create. Set applicationIdSuffix " +
                        "on that build type itself, or drop it from coldSpot { }.",
                )
            }
            // Otherwise debug's application ID, which initWith copied along with the suffix, so that everything keyed
            // on it (Firebase, Sign-In, Maps keys, push) keeps working.
            applicationIdSuffix != null -> buildType.applicationIdSuffix = applicationIdSuffix
        }
    }

    /**
     * The build type called [name], created from `debug` if the module has none, with `debug` among its fallbacks
     * either way, so that a dependency left out of ColdSpot still resolves. Says whether it was created.
     *
     * AGP's own coverage is switched off in the build type ColdSpot creates (C1): ColdSpot instruments what it
     * selects itself. A build type the module defines keeps every setting of its own, but one with
     * `enableAndroidTestCoverage` on that is also the `testBuildType` is refused: for that build type alone AGP
     * runs its JaCoCo after every scoped-artifact transform, so over ColdSpot's probes, and JaCoCo refuses
     * classes that already carry probes. With another `testBuildType` the flag is inert and left alone.
     */
    private fun <T : BuildType> prepareBuildType(android: TestedExtension, buildTypes: NamedDomainObjectContainer<T>, name: String): Pair<T, Boolean> {
        val existing = buildTypes.findByName(name)
        val buildType = existing ?: buildTypes.create(name).apply {
            initWith(buildTypes.getByName(DEBUG))
            enableAndroidTestCoverage = false
        }
        if (existing != null && existing.enableAndroidTestCoverage && android.testBuildType == name) {
            throw GradleException(
                "ColdSpot: build type '$name' is defined by this module with enableAndroidTestCoverage = true and is the " +
                    "testBuildType, so AGP would run its own JaCoCo over the classes ColdSpot already instrumented, and JaCoCo " +
                    "refuses instrumented input (\"Cannot process instrumented class\"). Choose one: let ColdSpot create its own " +
                    "build type (drop '$name' from buildTypes, or point coldSpot { buildTypeName = \"...\" } at a name this module " +
                    "does not define); set enableAndroidTestCoverage = false on '$name'; or make another build type the testBuildType.",
            )
        }
        if (DEBUG !in buildType.matchingFallbacks) buildType.matchingFallbacks += DEBUG
        return buildType to (existing == null)
    }

    /**
     * Coverage = debug + ColdSpot: every dependency configuration of the coverage build type extends its debug twin
     * (`coverageImplementation` extends `debugImplementation`, `demoCoverageRuntimeOnly` extends `demoDebugRuntimeOnly`,
     * `kspCoverage` extends `kspDebug`), because `initWith` copies a build type's properties, never its dependencies.
     * Wired as configurations appear, whichever of a pair comes second; only dependency scopes, never the resolvable
     * classpaths or the consumable elements AGP derives from them.
     */
    private fun extendDebugConfigurations(project: Project, buildType: String) {
        project.configurations.configureEach { added -> wireToDebugTwin(project, added, buildType) }
    }

    /**
     * The same, over every configuration, once the project is evaluated. A configuration's role is set after it is
     * created, which is when `configureEach` sees it, and AGP's variant configurations (`freeCoverageImplementation`)
     * pass for resolvable and consumable at that moment; by now every role is final.
     */
    private fun extendDebugConfigurationsOnceMore(project: Project, buildType: String) {
        project.configurations.forEach { wireToDebugTwin(project, it, buildType) }
    }

    private fun wireToDebugTwin(project: Project, configuration: Configuration, buildType: String) {
        val configurations = project.configurations
        val debugTwin = twinConfigurationName(configuration.name, buildType, DEBUG)
        if (debugTwin != null && configuration.isDependencyScope()) configurations.findByName(debugTwin)?.let { configuration.extendsFrom(it) }
        val coverageTwin = twinConfigurationName(configuration.name, DEBUG, buildType)
        if (coverageTwin != null) configurations.findByName(coverageTwin)?.takeIf { it.isDependencyScope() }?.extendsFrom(configuration)
    }

    /** AGP's buckets can be neither resolved nor consumed; kapt's and KSP's are resolved by their own tasks, but never consumed. */
    private fun Configuration.isDependencyScope(): Boolean =
        !isCanBeConsumed && (!isCanBeResolved || name.startsWith(KSP_PREFIX) || name.startsWith(KAPT_PREFIX))

    private fun registerBundleTask(project: Project, variant: Variant, extension: ColdSpotExtension, sharedManifest: Boolean) {
        val bundle = project.tasks.register(bundleTaskName(variant.name), ColdSpotBundleTask::class.java) { task ->
            task.description =
                "Instruments the changed classes of ${variant.name} and bundles their original bytes as assets, from the build's one diff."
            task.repoDir.set(project.layout.settingsDirectory)
            task.baseRef.set(extension.effectiveBaseRef)
            task.moduleFolder.set(moduleFolder(project.path))
            task.excludes.set(extension.excludes)
            task.sharedManifest.set(sharedManifest)
            task.compileClasspath.from(variant.compileClasspath)
            task.jacocoVersion.set(jacocoMavenVersion())
            task.jacocoBuild.set(JaCoCo.VERSION)
        }
        variant.artifacts
            .forScope(ScopedArtifacts.Scope.PROJECT)
            .use(bundle)
            .toTransform(ScopedArtifact.CLASSES, ColdSpotBundleTask::classJars, ColdSpotBundleTask::classDirs, ColdSpotBundleTask::transformedJar)
        val assets = checkNotNull(variant.sources.assets) { "ColdSpot: variant ${variant.name} has no assets to add the bundle to" }
        assets.addGeneratedSourceDirectory(bundle, ColdSpotBundleTask::outputDir)
    }

    /**
     * JaCoCo on the coverage variant's classpaths: compile-only for the module's own code, packaged only in that APK,
     * and at the instrumenter's version whatever else on the runtime classpath asks for another, as AGP does for its
     * own agent (`TaskManager.handleJacocoDependencies`): the analyser on the device must place probes exactly as
     * the instrumenter did, and Gradle would otherwise let a newer JaCoCo from any dependency win.
     */
    private fun addJacocoRuntime(project: Project, variant: Variant) {
        val version = jacocoMavenVersion()
        val core = "org.jacoco:org.jacoco.core:$version"
        val agent = "org.jacoco:org.jacoco.agent:$version:runtime"
        variant.compileConfiguration.dependencies.add(project.dependencies.create(core))
        variant.runtimeConfiguration.dependencies.add(project.dependencies.create(core))
        variant.runtimeConfiguration.dependencies.add(project.dependencies.create(agent))
        variant.runtimeConfiguration.resolutionStrategy.force(core, agent)
    }

    /** The `jacoco-agent.properties` resource the offline runtime needs at its first probe; see [ColdSpotAgentPropertiesTask]. */
    private fun addAgentProperties(project: Project, variant: Variant) {
        val properties = project.tasks.register("coldSpotAgentProperties" + variant.name.replaceFirstChar { it.uppercase() }, ColdSpotAgentPropertiesTask::class.java) {
            it.description = "Writes the jacoco-agent.properties the ${variant.name} APK carries for JaCoCo's offline runtime."
        }
        val resources = checkNotNull(variant.sources.resources) { "ColdSpot: variant ${variant.name} has no Java resources to add jacoco-agent.properties to" }
        resources.addGeneratedSourceDirectory(properties, ColdSpotAgentPropertiesTask::outputDir)
    }

    /**
     * The Maven version of the jacoco-core the instrumenter comes from, read off its own jar: [JaCoCo.VERSION] is the
     * qualified build version (`0.8.14.202510111229`), which is not a coordinate.
     */
    private fun jacocoMavenVersion(): String {
        val pom = JaCoCo::class.java.getResourceAsStream("/META-INF/maven/org.jacoco/org.jacoco.core/pom.properties")
        val version = pom?.use { java.util.Properties().apply { load(it) }.getProperty("version") }
        return checkNotNull(version) { "ColdSpot: cannot tell jacoco-core's Maven version from its jar (JaCoCo.VERSION = ${JaCoCo.VERSION})" }
    }

    /** `coldSpotBundleCoverage`, `coldSpotBundleFreeCoverage`: AGP's own verb-then-variant shape. */
    private fun bundleTaskName(variantName: String): String = "coldSpotBundle" + variantName.replaceFirstChar { it.uppercase() }

    /** `:feature` -> `feature`, `:lib:core` -> `lib/core`, the root project -> `root`. */
    private fun moduleFolder(projectPath: String): String = projectPath.removePrefix(":").replace(':', '/').ifEmpty { "root" }

    private companion object {
        const val EXTENSION_NAME = "coldSpot"
        const val DEFAULT_BUILD_TYPE = "coverage"
        const val DEBUG = "debug"
        const val KSP_PREFIX = "ksp"
        const val KAPT_PREFIX = "kapt"
        const val ANDROID_APPLICATION = "com.android.application"
        const val ANDROID_LIBRARY = "com.android.library"
    }
}

package id.tensky.coldspot.plugin

/**
 * The debug counterpart of a dependency configuration of the coverage build type, by name: `coverageImplementation`
 * is `debugImplementation`'s twin, `demoCoverageRuntimeOnly` is `demoDebugRuntimeOnly`'s, `kspCoverage` is
 * `kspDebug`'s. AGP, kapt and KSP all spell a build type into a configuration name the same way, as one camel-case
 * word, first when it leads (`coverageApi`) and capitalised after a flavor or a prefix (`kspDemoCoverage`), so the
 * twin is the name with that word swapped. Null when the name does not carry the build type as a word.
 */
internal fun twinConfigurationName(name: String, buildType: String, twin: String): String? {
    if (name.startsWith(buildType) && name.length > buildType.length && name[buildType.length].isUpperCase()) {
        return twin + name.substring(buildType.length)
    }
    val word = buildType.replaceFirstChar { it.uppercase() }
    var from = 1
    while (from < name.length) {
        val at = name.indexOf(word, from)
        if (at < 1) return null
        val end = at + word.length
        val wordEnds = end == name.length || name[end].isUpperCase()
        if (!name[at - 1].isUpperCase() && wordEnds) return name.substring(0, at) + twin.replaceFirstChar { it.uppercase() } + name.substring(end)
        from = at + 1
    }
    return null
}

package id.tensky.coldspot.plugin.tools

import org.jacoco.core.analysis.Analyzer
import org.jacoco.core.analysis.CoverageBuilder
import org.jacoco.core.data.ExecutionDataReader
import org.jacoco.core.data.ExecutionDataStore
import org.jacoco.core.data.SessionInfoStore
import java.io.ByteArrayInputStream
import java.io.File
import java.util.Base64
import java.util.TreeMap
import java.util.zip.ZipFile
import kotlin.system.exitProcess

/**
 * Re-runs the device's analysis on the laptop and diffs the two. The Logcat dump holds what the sample's
 * CoverageDebug logged: the agent's execution data (`EXEC i/n <base64>` chunks) and one `LINE <class> <line>
 * <covered>/<total>` row per executable line, plus `CLASS ... noMatch=<bool>`. The APK holds the shipped bytes
 * under `assets/coldspot/<module>/classes/`. Same JaCoCo, same bytes, same execution data: the rows must match.
 *
 *     ./gradlew :tooling:plugin:checkDeviceRun -q -Plogcat=<dump> -Papk=<apk>
 *
 * Prints every difference and exits 1 if there is one.
 */
public fun main(args: Array<String>) {
    val logcat = File(args[0]).readLines()
    val apk = File(args[1])

    val exec = executionData(logcat)
    val store = ExecutionDataStore()
    ExecutionDataReader(ByteArrayInputStream(exec)).apply {
        setExecutionDataVisitor(store)
        setSessionInfoVisitor(SessionInfoStore())
        read()
    }

    val laptopLines = TreeMap<String, String>()
    val laptopNoMatch = TreeMap<String, Boolean>()
    ZipFile(apk).use { zip ->
        for (entry in zip.entries().asSequence().filter { it.name.startsWith("assets/coldspot/") && it.name.endsWith(".class") }) {
            val builder = CoverageBuilder()
            Analyzer(store, builder).analyzeClass(zip.getInputStream(entry).use { it.readBytes() }, entry.name)
            for (cls in builder.classes) {
                laptopNoMatch[cls.name] = cls.isNoMatch
                if (cls.firstLine < 0) continue
                for (line in cls.firstLine..cls.lastLine) {
                    val counter = cls.getLine(line).instructionCounter
                    if (counter.totalCount > 0) laptopLines["${cls.name} $line"] = "${counter.coveredCount}/${counter.totalCount}"
                }
            }
        }
    }

    val deviceLines = TreeMap<String, String>()
    val deviceNoMatch = TreeMap<String, Boolean>()
    for (line in logcat) {
        LINE_ROW.find(line)?.let { deviceLines["${it.groupValues[1]} ${it.groupValues[2]}"] = it.groupValues[3] }
        CLASS_ROW.find(line)?.let { deviceNoMatch[it.groupValues[1]] = it.groupValues[2].toBoolean() }
    }

    var differences = 0
    for (key in (laptopLines.keys + deviceLines.keys).toSortedSet()) {
        val laptop = laptopLines[key]
        val device = deviceLines[key]
        if (laptop != device) {
            differences++
            println("$key: device ${device ?: "-"}, laptop ${laptop ?: "-"}")
        }
    }
    for (key in (laptopNoMatch.keys + deviceNoMatch.keys).toSortedSet()) {
        if (laptopNoMatch[key] != deviceNoMatch[key]) {
            differences++
            println("$key: noMatch device ${deviceNoMatch[key] ?: "-"}, laptop ${laptopNoMatch[key] ?: "-"}")
        }
    }
    println(
        "${exec.size} bytes of execution data, ${laptopNoMatch.size} classes on the laptop / ${deviceNoMatch.size} on the device, " +
            "${laptopLines.size} lines / ${deviceLines.size}: ${if (differences == 0) "identical" else "$differences differences"}",
    )
    if (differences > 0) exitProcess(1)
}

/** The `EXEC i/n <chunk>` lines joined in order and decoded. */
private fun executionData(logcat: List<String>): ByteArray {
    val chunks = TreeMap<Int, String>()
    var expected = 0
    for (line in logcat) {
        val match = EXEC_ROW.find(line) ?: continue
        chunks[match.groupValues[1].toInt()] = match.groupValues[3]
        expected = match.groupValues[2].toInt()
    }
    require(chunks.isNotEmpty()) { "no EXEC lines in the dump" }
    require(chunks.size == expected) { "found ${chunks.size} of $expected EXEC chunks" }
    return Base64.getDecoder().decode(chunks.values.joinToString(""))
}

private val EXEC_ROW = Regex("""ColdSpot.*\bEXEC (\d+)/(\d+) (\S+)""")
private val LINE_ROW = Regex("""ColdSpot.*\bLINE (\S+) (\d+) (\d+/\d+)""")
private val CLASS_ROW = Regex("""ColdSpot.*\bCLASS (\S+) .*noMatch=(true|false)""")
